What number does this program print?

```cpp
#include <atomic>
#include <print>
#include <thread>
#include <vector>

int main() {
    std::atomic<int> total{0};
    {
        std::vector<std::jthread> ts;
        for (int t = 0; t < 3; ++t) {
            ts.emplace_back([&total] {
                for (int i = 0; i < 1000; ++i) total += 2;
            });
        }
    }
    std::println("{}", total.load());
}
```

Four threads push values in an unpredictable order. What does the program print?

```cpp
std::mutex m;
std::vector<int> ids;
{
    std::vector<std::jthread> ts;
    for (int t = 3; t >= 0; --t) {
        ts.emplace_back([&, t] {
            std::scoped_lock lock{m};
            ids.push_back(t * t);
        });
    }
}
std::ranges::sort(ids);
for (int x : ids) std::print("{} ", x);
std::println("");
```
